"""Preserve exact generated bytes and one per-image production record."""
from pathlib import Path
import json, shutil, hashlib, sys
sys.path.insert(0,'C:/Users/wseok/.cache/codex-media-tools/faster-whisper')
from PIL import Image
R=Path(__file__).resolve().parent
req=json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
u=next(x for x in json.loads((R/'storyboards.json').read_text(encoding='utf-8'))['generation_units'] if x['id']==req['id'])
source=Path(req['source_generated_path']); dest=R/req.get('image_path',u['image_file']);dest.parent.mkdir(parents=True,exist_ok=True)
if dest.exists():raise RuntimeError('Refusing to overwrite '+str(dest))
shutil.copyfile(source,dest)
digest=hashlib.sha256(dest.read_bytes()).hexdigest()
assert digest==hashlib.sha256(source.read_bytes()).hexdigest()
with Image.open(dest) as im:im.load();dims=list(im.size)
f=R/('artist_'+u['concept_id']+'.json')
d=json.loads(f.read_text(encoding='utf-8')) if f.exists() else {'concept_id':u['concept_id'],'expected_images':9,'images':[]}
entry={'id':u['id'],'concept_id':u['concept_id'],'scene_id':u['scene_id'],'linked_cut':u['linked_shot'],'image_path':dest.relative_to(R).as_posix(),'source_generated_path':str(source),'generation_tool':'image_gen','prompt':req['prompt'],'referenced_image_paths':req['referenced_image_paths'],'next_motion':u['action'],'camera_notes':u['framing'],'sha256':digest,'dimensions':dims,'artist_review':{'opened_actual_image':True,'status':'candidate','notes':req['observations']},'attempts':[]}
old=next((x for x in d['images'] if x['id']==u['id']),None)
if old:
 entry['attempts']=old.get('attempts',[])+[{k:old[k] for k in ['image_path','source_generated_path','prompt','referenced_image_paths','sha256','artist_review']}]
 d['images']=[entry if x['id']==entry['id'] else x for x in d['images']]
else:d['images'].append(entry)
f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'id':u['id'],'image':entry['image_path'],'dimensions':dims,'sha256':digest}))
